const b = $json.body || {};
if (!b.drift_found && !(b.check_errors && b.check_errors.length)) {
  return [];
}
const lines = [':mag: **Doc drift detected** (`scripts/drift_check.py`)'];
for (const [check, items] of Object.entries(b.findings || {})) {
  lines.push(`\n__${check}__ (${items.length}):`);
  for (const it of items) lines.push(`\u2022 ${it.detail}`);
}
for (const e of b.check_errors || []) {
  lines.push(`\n:warning: check **${e.check}** errored: ${e.error}`);
}
const body = (b.findings ? Object.values(b.findings).flat().map(i => '- ' + i.detail).join('\n') : '');
const issueUrl = 'https://git.example.lab/ops/homelab/issues/new?title='
  + encodeURIComponent('doc drift: ' + (new Date().toISOString().slice(0,10)))
  + '&body=' + encodeURIComponent('`scripts/drift_check.py` findings:\n\n' + body);
lines.push(`\n[open a tracking issue](${issueUrl})`);
let content = lines.join('\n');
if (content.length > 1900) content = content.slice(0, 1890) + '\n\u2026(truncated)';
return [{ json: { content } }];
